package local.paladinprobe;
import java.nio.file.*;import java.util.*;import com.google.gson.*;import com.mojang.serialization.JsonOps;
import net.neoforged.fml.common.Mod;import net.neoforged.neoforge.common.NeoForge;import net.neoforged.neoforge.event.server.ServerStartedEvent;import net.neoforged.neoforge.common.util.FakePlayerFactory;
import net.minecraft.core.registries.*;import net.minecraft.core.component.DataComponents;import net.minecraft.resources.Identifier;import net.minecraft.world.item.*;import net.minecraft.world.item.enchantment.*;import net.minecraft.world.entity.*;
@Mod("paladin_doctrine_probe") public class NodeProbe {
 List<String> checks=new ArrayList<>();int fail;void test(boolean ok,String l){checks.add((ok?"PASS ":"FAIL ")+l);if(!ok)fail++;}void near(double a,double b,String l){test(Math.abs(a-b)<.0001,l+" actual="+a+" expected="+b);}
 public NodeProbe(){NeoForge.EVENT_BUS.addListener(this::run);}
 void run(ServerStartedEvent e){var s=e.getServer();try{var w=s.overworld();var p=FakePlayerFactory.getMinecraft(w);p.getInventory().clearContent();p.removeAllEffects();var r=w.registryAccess().lookupOrThrow(Registries.ENCHANTMENT);var ff=r.get(Identifier.parse("minecraft:feather_falling")).orElseThrow();
 for(int l=1;l<=4;l++){var boots=new ItemStack(Items.DIAMOND_BOOTS);boots.enchant(ff,l);p.setItemSlot(EquipmentSlot.FEET,boots);float epf=EnchantmentHelper.getDamageProtection(w,p,w.damageSources().fall());near(epf,1.5*l,"native fall protection points level "+l);near(net.minecraft.world.damagesource.CombatRules.getDamageAfterMagicAbsorb(100,epf),100-6*l,"fall damage reduction level "+l);near(EnchantmentHelper.getDamageProtection(w,p,w.damageSources().generic()),0,"no general damage reduction level "+l);}
 test(r.get(Identifier.parse("toughness_enchantment:toughness")).isEmpty(),"Toughness absent from registry");test(!net.neoforged.fml.ModList.get().isLoaded("mr_toughness_enchantment"),"Toughness addon absent");
 var ops=w.registryAccess().createSerializationContext(JsonOps.INSTANCE);
 for(boolean book:new boolean[]{false,true}){var root=new JsonObject();root.addProperty("id",book?"minecraft:enchanted_book":"minecraft:diamond_boots");root.addProperty("count",1);var c=new JsonObject();var ench=new JsonObject();ench.addProperty("minecraft:feather_falling",4);ench.addProperty("toughness_enchantment:toughness",3);c.add(book?"minecraft:stored_enchantments":"minecraft:enchantments",ench);c.add("penchant:enchantment_progress",ench.deepCopy());root.add("components",c);
 try{var item=ItemStack.CODEC.parse(ops,root).getOrThrow();var stored=item.get(book?DataComponents.STORED_ENCHANTMENTS:DataComponents.ENCHANTMENTS);test(stored.size()==1,"legacy "+(book?"book":"gear")+" loses only Toughness");near(stored.getLevel(ff),4,"legacy Feather Falling level retained");var nbt=JsonOps.INSTANCE.convertTo(net.minecraft.nbt.NbtOps.INSTANCE,root);var nops=w.registryAccess().createSerializationContext(net.minecraft.nbt.NbtOps.INSTANCE);test(ItemStack.CODEC.parse(nops,nbt).getOrThrow().getItem()==item.getItem(),"legacy NBT item and progress survives");}catch(Throwable t){test(false,"legacy save decoding: "+t);}}
 CreativeModeTabs.tryRebuildTabContents(w.enabledFeatures(),true,w.registryAccess());int bad=0;for(var tab:CreativeModeTabs.allTabs())for(var stack:tab.getDisplayItems()){var ench=stack.get(DataComponents.STORED_ENCHANTMENTS);if(ench!=null)for(var h:ench.keySet())if(h.unwrapKey().orElseThrow().identifier().toString().equals("toughness_enchantment:toughness"))bad++;}near(bad,0,"no Toughness books in creative lists");
 }catch(Throwable t){fail++;checks.add("ERROR "+t);t.printStackTrace();}finally{try{Files.write(Path.of("paladin-checks.txt"),checks);Files.writeString(Path.of("paladin-result.txt"),(fail==0?"PASS ":"FAIL ")+checks.size()+" checks; failures="+fail);}catch(Exception x){throw new RuntimeException(x);}s.halt(false);}}
}